<script lang="ts">
 import PasswordField from './PasswordField.svelte';import Credentials from './Credentials.svelte';import {command,newId,validatePassword} from '$lib/database/store';import {engines,presets,type Engine,type Preset} from '$lib/database/model';
 export let database='';export let fixedEngine:Engine|undefined=undefined;
 let engine:Engine=fixedEngine||'MySQL',name='',password='',selectedPreset:Preset='Full access',error='',credentials:{username:string;password:string}|null=null;
 function submit(){try{validatePassword(password);command({type:'user',id:newId(),name:name.trim(),engine:fixedEngine||engine,database:database||undefined,preset:selectedPreset});credentials={username:name.trim(),password};name='';password='';error='';}catch(e){error=e instanceof Error?e.message:'User creation failed.';}}
</script>
<form class="card stack" on:submit|preventDefault={submit}><div><h3>Create user</h3><p class="subtitle">Create an independent database user with private access by default.</p></div><div class="db13-form-grid"><label class="field">Engine<select bind:value={engine} disabled={!!fixedEngine}>{#each engines as e}<option value={e}>{e}</option>{/each}</select></label><label class="field">Username<input required bind:value={name} placeholder="application_user"/></label></div><PasswordField bind:value={password} inputId="new-user-password"/>{#if database}<label class="field">Initial privileges<select bind:value={selectedPreset}>{#each presets as p}<option value={p}>{p}</option>{/each}</select></label>{/if}{#if error}<p class="error" role="alert">{error}</p>{/if}<div class="native-actions"><button class="btn primary" type="submit">Create user</button></div></form>{#if credentials}<Credentials username={credentials.username} password={credentials.password} onClose={()=>credentials=null}/>{/if}
